	description string
	price       float64
	quantity    int
	expected    float64
}

func main() {
	// Define the test cases including the required boundary conditions
	tests := []TestCase{
		{
			description: "Quantity 9 (No discount)",
			price:       100.0,
			quantity:    9,
			expected:    900.0,
		},
		{
			description: "Quantity 10 (10% discount boundary)",
			price:       100.0,
			quantity:    10,
			expected:    900.0,
