                var obj = new JsonObject
                {
                    ["Name"] = parts[0].Trim(),
                    ["Age"] = int.Parse(parts[1].Trim(), CultureInfo.InvariantCulture),
                    ["Email"] = parts[2].Trim(),
                    ["Score"] = float.Parse(parts[3].Trim(), CultureInfo.InvariantCulture)
