        Console.WriteLine($"PASS: {description}");
    }
    else
    {
        // Formatting expected and actual to 2 decimal places for readable output
        Console.WriteLine($"FAIL: {description} (expected: {expected:F2}, got: {actual:F2})");
    }
}

